383	/****************************************************************************
384	 * Name: ltdc_configure_layer
385	 *
386	 * Description:
387	 *   Configure LTDC layer 1
388	 *
389	 ****************************************************************************/
390	
391	static void ltdc_configure_layer(void)
392	{
393	  uint32_t regval;
394	
395	  /* Configure window horizontal position */
396	
397	  regval = LTDC_LXWHPCR_WHSTPOS(BOARD_LTDC_HSYNC + BOARD_LTDC_HBP) |
398	           LTDC_LXWHPCR_WHSPPOS(BOARD_LTDC_HSYNC + BOARD_LTDC_HBP +
399	                                 BOARD_LTDC_WIDTH - 1);
400	  ltdc_putreg(STM32_LTDC_L1WHPCR_OFFSET, regval);
401	
402	  /* Configure window vertical position */
403	
404	  regval = LTDC_LXWVPCR_WVSTPOS(BOARD_LTDC_VSYNC + BOARD_LTDC_VBP) |
405	           LTDC_LXWVPCR_WVSPPOS(BOARD_LTDC_VSYNC + BOARD_LTDC_VBP +
406	                                 BOARD_LTDC_HEIGHT - 1);
407	  ltdc_putreg(STM32_LTDC_L1WVPCR_OFFSET, regval);
408	
409	  /* Configure pixel format - RGB565 */
410	
411	  ltdc_putreg(STM32_LTDC_L1PFCR_OFFSET, LTDC_LXPFCR_RGB565);
412	
413	  /* Configure constant alpha */
414	
415	  ltdc_putreg(STM32_LTDC_L1CACR_OFFSET, 0xff);
416	
417	  /* Configure default color */
418	
419	  ltdc_putreg(STM32_LTDC_L1DCCR_OFFSET, 0x00000000);
420	
421	  /* Configure blending factors */
422	
423	  regval = LTDC_LXBFCR_BF1_PIXEL_ALPHA_x_CA |
424	           LTDC_LXBFCR_BF2_PIXEL_ALPHA_x_CA;
425	  ltdc_putreg(STM32_LTDC_L1BFCR_OFFSET, regval);
426	
427	  /* Configure color frame buffer address */
428	
429	  ltdc_putreg(STM32_LTDC_L1CFBAR_OFFSET, (uint32_t)g_ltdc_fb);
430	
431	  /* Configure color frame buffer length */
432	
433	  regval = LTDC_LXCFBLR_CFBLL(BOARD_LTDC_WIDTH * 2 + 3) |
434	           LTDC_LXCFBLR_CFBP(BOARD_LTDC_WIDTH * 2);
435	  ltdc_putreg(STM32_LTDC_L1CFBLR_OFFSET, regval);
436	
437	  /* Configure color frame buffer line number */
438	
439	  ltdc_putreg(STM32_LTDC_L1CFBLNR_OFFSET, BOARD_LTDC_HEIGHT);
440	
441	  /* Enable layer 1 */
442	
443	  ltdc_putreg(STM32_LTDC_L1CR_OFFSET, LTDC_LXCR_LEN);
444	
445	  /* Reload shadow registers - SRCR.IMR = immediate reload */
446	
447	  ltdc_modifyreg(STM32_LTDC_SRCR_OFFSET, 0, LTDC_SRCR_IMR);
448	
