455	
456	static int ltdc_getvideoinfo(struct fb_vtable_s *vplane,
457	                              struct fb_videoinfo_s *vinfo)
458	{
459	  struct stm32_ltdc_priv_s *priv = (struct stm32_ltdc_priv_s *)vplane;
460	
461	  DEBUGASSERT(priv != NULL && vinfo != NULL);
462	
463	  lcdinfo("vplane=%p vinfo=%p\n", vplane, vinfo);
464	
465	  vinfo->fmt = FB_FMT_RGB16_565;
466	  vinfo->xres = priv->width;
467	  vinfo->yres = priv->height;
468	  vinfo->nplanes = 1;
469	
470	  return OK;
471	}
472	
473	static int ltdc_getplaneinfo(struct fb_vtable_s *vplane, int planeno,
474	                              struct fb_planeinfo_s *pinfo)
475	{
476	  struct stm32_ltdc_priv_s *priv = (struct stm32_ltdc_priv_s *)vplane;
477	
478	  DEBUGASSERT(priv != NULL && pinfo != NULL && planeno == 0);
479	
480	  lcdinfo("vplane=%p planeno=%d pinfo=%p\n", vplane, planeno, pinfo);
481	
482	  pinfo->fbmem = priv->fbmem;
483	  pinfo->fblen = priv->width * priv->height * (priv->bpp / 8);
484	  pinfo->stride = priv->width * (priv->bpp / 8);
485	  pinfo->display = 0;
486	  pinfo->bpp = priv->bpp;
487	
488	  return OK;
489	}
